func (s Rules) JSONSize() int {
	size := 349
	size += len(s.Aff) * 2
	size += len(s.Bytes) * 2
	size += len(s.Code) * 2
	size += len(s.Digits) * 2
	size += len(s.Eq) * 2
	size += len(s.HexS) * 2
	size += len(s.Kind) * 2
	size += len(s.Link) * 2
	size += len(s.Low) * 2
	size += len(s.Lower) * 2
	size += len(s.Name) * 2
	if s.Opt == nil {
		size += 4
	} else {
		size += 20
	}
	size += len(s.Runes) * 2
	size += len(s.Tr) * 2
	size += len(s.Up) * 2
	return size
}

func (s Rules) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"aff\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Aff)
	dst = append(dst, ",\"bytes\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Bytes)
	dst = append(dst, ",\"clamp\":"...)
	dst = strconv.AppendInt(dst, int64(s.Clamp), 10)
	dst = append(dst, ",\"code\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Code)
	dst = append(dst, ",\"conv\":"...)
	dst = strconv.AppendInt(dst, int64(s.Conv), 10)
	dst = append(dst, ",\"digits\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Digits)
	dst = append(dst, ",\"eq\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Eq)
	dst = append(dst, ",\"even\":"...)
	dst = strconv.AppendInt(dst, int64(s.Even), 10)
	dst = append(dst, ",\"even2\":"...)
	dst = strconv.AppendInt(dst, int64(s.Even2), 10)
	dst = append(dst, ",\"hex_s\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.HexS)
	dst = append(dst, ",\"kind\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Kind)
	dst = append(dst, ",\"level\":"...)
	dst = strconv.AppendInt(dst, int64(s.Level), 10)
	dst = append(dst, ",\"link\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Link)
	dst = append(dst, ",\"low\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Low)
	dst = append(dst, ",\"lower\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Lower)
	dst = append(dst, ",\"name\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Name)
	dst = append(dst, ",\"nz\":"...)
	dst = strconv.AppendInt(dst, int64(s.NZ), 10)
	dst = append(dst, ",\"opt\":"...)
	if s.Opt == nil {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendInt(dst, int64((*s.Opt)), 10)
	}
	dst = append(dst, ",\"runes\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Runes)
	dst = append(dst, ",\"score\":"...)
	if dst, err = ggen.AppendFloat(dst, s.Score, 64); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"tr\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Tr)
	dst = append(dst, ",\"up\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Up)
	return append(dst, '}'), nil
}

